import 'package:pulumi/pulumi.dart' as pulumi;

/// The severity to relate to the assessments generated by this Recommendation.
enum SecurityIssue implements pulumi.PulumiEnum<String> {
  vulnerability("Vulnerability"),
  excessivePermissions("ExcessivePermissions"),
  anonymousAccess("AnonymousAccess"),
  networkExposure("NetworkExposure"),
  trafficEncryption("TrafficEncryption"),
  bestPractices("BestPractices");

  const SecurityIssue(this.wireValue);
  @override
  final String wireValue;

  static SecurityIssue fromValue(String value) {
    for (final item in SecurityIssue.values) {
      if (item.wireValue == value) {
        return item;
      }
    }
    throw ArgumentError('Unknown SecurityIssue value: $value');
  }
}
